#include <iostream>
#include <algorithm>
using namespace std;

long long N, K;
const long long MOD = 1000000007LL;
long long Power[65], Res[35][35];
long long S[65][35][35][35], A[65][35][35][35], P[65][35][35][35], Aux[35][35];

inline void addMod(long long& a, long long b) {
    a = (a + b) % MOD;
}

void copyMatrix(long long dest[][35], long long src[][35], long long n) {
    for (long long i = 0; i < n; ++i)
        for (long long j = 0; j < n; ++j)
            dest[i][j] = src[i][j];
}

void matrixMultiply(long long X[][35], long long Y[][35], long long Z[][35], long long n, long long m, long long p) {
    for (long long i = 0; i < n; ++i) {
        for (long long j = 0; j < p; ++j) {
            Z[i][j] = 0;
            for (long long k = 0; k < m; ++k) {
                addMod(Z[i][j], (X[i][k] * Y[k][j]) % MOD);
            }
        }
    }
}

void precomputeA() {
    for (long long x = 0; x < K; ++x) {
        for (long long i = 0; i < K + 1; ++i) {
            A[0][x][i][i] = 1;
        }
        for (long long j = 0; j < K + 1; ++j) {
            A[0][x][j][x] = 1;
        }
    }

    copyMatrix(P[0][0], A[0][0], K + 1);
    copyMatrix(S[0][K - 1], A[0][K - 1], K + 1);

    for (long long x = 1; x < K; ++x) {
        matrixMultiply(P[0][x - 1], A[0][x], P[0][x], K + 1, K + 1, K + 1);
    }

    for (long long x = K - 2; x >= 0; --x) {
        matrixMultiply(A[0][x], S[0][x + 1], S[0][x], K + 1, K + 1, K + 1);
    }

    long long multiplier = 1;
    int level = 0;
    while (multiplier <= N / K) {
        for (long long x = 0; x < K; ++x) {
            if (x > 0) {
                copyMatrix(A[level][x], S[level - 1][x], K + 1);
                matrixMultiply(A[level][x], P[level - 1][x - 1], Aux, K + 1, K + 1, K + 1);
                copyMatrix(A[level][x], Aux, K + 1);
            } else {
                copyMatrix(A[level][x], S[level - 1][x], K + 1);
            }
        }
        copyMatrix(P[level][0], A[level][0], K + 1);
        copyMatrix(S[level][K - 1], A[level][K - 1], K + 1);

        for (long long x = 1; x < K; ++x) {
            matrixMultiply(P[level][x - 1], A[level][x], P[level][x], K + 1, K + 1, K + 1);
        }

        for (long long x = K - 2; x >= 0; --x) {
            matrixMultiply(A[level][x], S[level][x + 1], S[level][x], K + 1, K + 1, K + 1);
        }

        if (multiplier > N / K / K) break;
        multiplier *= K;
        ++level;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> N >> K;

    Power[0] = 1;
    int powerIndex = 1;
    while (Power[powerIndex - 1] <= N / K) {
        Power[powerIndex] = Power[powerIndex - 1] * K;
        ++powerIndex;
    }

    int maxPowerIndex = powerIndex - 1;
    precomputeA();

    long long remaining = N;
    int digitIndex = 0;
    for (int i = 0; i <= K; ++i)
        for (int j = 0; j <= K; ++j)
            Res[i][j] = 0;
    Res[0][K] = 1;

    for (int p = maxPowerIndex; p >= 0; --p) {
        while (Power[p] <= remaining) {
            for (int i = 0; i <= K; ++i) {
                for (int j = 0; j <= K; ++j) {
                    Aux[i][j] = 0;
                    for (int k = 0; k <= K; ++k) {
                        addMod(Aux[i][j], (Res[i][k] * A[p][digitIndex][k][j]) % MOD);
                    }
                }
            }
            for (int i = 0; i <= K; ++i)
                for (int j = 0; j <= K; ++j)
                    Res[i][j] = Aux[i][j];
            digitIndex = (digitIndex + 1) % K;
            remaining -= Power[p];
        }
    }

    long long answer = 0;
    for (int i = 0; i <= K; ++i) {
        addMod(answer, Res[0][i]);
    }
    cout << answer << '\n';
    return 0;
}
